module TopModule (
    input  clk,
    input  d,
    output q
);

    // Internal wires for each bit of the 8-bit register
    wire [7:0] d_wire;
    wire [7:0] q_wire;

    // Assign input d to all 8 bits
    assign d_wire = d;

    // Instantiate 8 D flip-flops
    DFF dff0 (.d(d_wire[0]), .clk(clk), .q(q_wire[0]));
    DFF dff1 (.d(d_wire[1]), .clk(clk), .q(q_wire[1]));
    DFF dff2 (.d(d_wire[2]), .clk(clk), .q(q_wire[2]));
    DFF dff3 (.d(d_wire[3]), .clk(clk), .q(q_wire[3]));
    DFF dff4 (.d(d_wire[4]), .clk(clk), .q(q_wire[4]));
    DFF dff5 (.d(d_wire[5]), .clk(clk), .q(q_wire[5]));
    DFF dff6 (.d(d_wire[6]), .clk(clk), .q(q_wire[6]));
    DFF dff7 (.d(d_wire[7]), .clk(clk), .q(q_wire[7]));

    // Assign output q from the register
    assign q = q_wire;

endmodule

