module TopModule (
    input  [4:0] a,
    input  [4:0] b,
    input  [4:0] c,
    input  [4:0] d,
    input  [4:0] e,
    input  [4:0] f,
    output [7:0] w,
    output [7:0] x,
    output [7:0] y,
    output [7:0] z
);

    // Concatenate all input vectors and add two 1 bits at the LSB
    wire [31:0] data = {a, b, c, d, e, f, 2'b01};

    // Split the 32-bit data into four 8-bit outputs
    assign w = data[7:0];
    assign x = data[15:8];
    assign y = data[23:16];
    assign z = data[31:24];

endmodule

