module TopModule (
    input  [2:0] sel,
    input  [3:0] data0,
    input  [3:0] data1,
    input  [3:0] data2,
    input  [3:0] data3,
    input  [3:0] data4,
    input  [3:0] data5,
    output reg [3:0] out
);

always @(*) begin
    case (sel)
        3'b000: out = data0;
        3'b001: out = data1;
        3'b010: out = data2;
        3'b011: out = data3;
        3'b100: out = data4;
        3'b101: out = data5;
        default: out = 4'b0000;
    endcase
end

endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for input values 2, 7, 15
    // Binary representations:
    // 2: 0010
    // 7: 0111
    // 15: 1111
    // SOP expression: a'bc'd + a'bcd + abcd'

    assign out_sop = (!a & b & !c & d) | (!a & b & c & d) | (a & b & c & !d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 0 for input values 0, 1, 4, 5, 6, 9, 10, 13, 14
    // Binary representations:
    // 0: 0000
    // 1: 0001
    // 4: 0100
    // 5: 0101
    // 6: 0110
    // 9: 1001
    // 10: 1010
    // 13: 1101
    // 14: 1110
    // POS expression: (a + b' + c' + d') * (a + b' + c + d') * (a + b + c' + d') * (a + b + c + d) * (a' + b + c + d) * (a' + b + c' + d) * (a' + b' + c + d) * (a' + b' + c' + d)

    assign out_pos = 
        (a | !b | !c | !d) &
        (a | !b | c | !d) &
        (a | b | !c | !d) &
        (a | b | c | d) &
        (!a | b | c | d) &
        (!a | b | !c | d) &
        (!a | !b | c | d) &
        (!a | !b | !c | d);

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [9:0] data,
    output reg tc
);

    reg [9:0] counter;

    always @(posedge clk) begin
        if (load) begin
            counter <= data;
            tc <= 1'b0;
        end else begin
            if (counter == 10'd0) begin
                tc <= 1'b1;
            end else begin
                counter <= counter - 1;
                tc <= 1'b0;
            end
        end
    end

endmodule

