module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // Next state logic
    always @(*) begin
        case (state)
            4'b0001: // A
                next_state = (in == 1'b0) ? 4'b0001 : 4'b0010;
            4'b0010: // B
                next_state = (in == 1'b0) ? 4'b0100 : 4'b0010;
            4'b0100: // C
                next_state = (in == 1'b0) ? 4'b0001 : 4'b1000;
            4'b1000: // D
                next_state = (in == 1'b0) ? 4'b0100 : 4'b0010;
            default: next_state = 4'b0000;
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    always @(*) begin
        case (state)
            4'b0001: out = 1'b0;
            4'b0010: out = 1'b0;
            4'b0100: out = 1'b0;
            4'b1000: out = 1'b1;
            default: out = 1'b0;
        endcase
    end

endmodule

