module TopModule (
    input  [2:0] y,
    input        w,
    output       Y1
);

    // State codes:
    // A = 000, B = 001, C = 010, D = 011, E = 100, F = 101

    // Next-state logic for y[1]
    // y[1] is the second bit of the state code

    // Current state
    reg [2:0] current_state;

    // Assign current_state from input y
    always @(y) begin
        current_state = y;
    end

    // Next state logic
    reg [2:0] next_state;

    always @(current_state, w) begin
        case (current_state)
            3'b000: // A
                if (w) next_state = 3'b000;
                else next_state = 3'b001;
            3'b001: // B
                if (w) next_state = 3'b010;
                else next_state = 3'b011;
            3'b010: // C
                if (w) next_state = 3'b100;
                else next_state = 3'b011;
            3'b011: // D
                if (w) next_state = 3'b000;
                else next_state = 3'b101;
            3'b100: // E
                if (w) next_state = 3'b100;
                else next_state = 3'b101;
            3'b101: // F
                if (w) next_state = 3'b010;
                else next_state = 3'b101;
            default: next_state = 3'b000;
        endcase
    end

    // Output Y1 is y[1]
    assign Y1 = y[1];

