module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1'b1 && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == FALLING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                aaah <= 1'b0;
            end else if (dig && current_state == WALK_LEFT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (dig && current_state == WALK_RIGHT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                digging <= 1'b0;
            end else if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                if (bump_left) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                end
            end

            // Update state
            current_state <= next_state;

            // Update previous direction
            if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                prev_direction <= (current_state == WALK_LEFT) ? 1'b1 : 1'b0;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);

    // Current state of the game
    reg [255:0] current_q;

    // Next state of the game
    reg [255:0] next_q;

    // Internal variables for neighbor count
    reg [255:0] neighbor_count;

    // Function to compute the number of live neighbors for a cell
    function [7:0] count_neighbors;
        input [7:0] row;
        input [7:0] col;
        // 8 neighbors in a toroidal 16x16 grid
        // (row-1, col-1), (row-1, col), (row-1, col+1)
        // (row, col-1),          (row, col+1)
        // (row+1, col-1), (row+1, col), (row+1, col+1)
        // Use modulo 16 to wrap around
        reg [7:0] r1, c1, r2, c2, r3, c3;
        r1 = row - 1;
        c1 = col - 1;
        r2 = row - 1;
        c2 = col;
        r3 = row - 1;
        c3 = col + 1;
        r1 = r1 % 16;
        c1 = c1 % 16;
        r2 = r2 % 16;
        c2 = c2 % 16;
        r3 = r3 % 16;
        c3 = c3 % 16;

        // Check if the neighbor is alive
        if (current_q[(r1*16 + c1)]) count_neighbors = count_neighbors + 1;
        if (current_q[(r2*16 + c2)]) count_neighbors = count_neighbors + 1;
        if (current_q[(r3*16 + c3)]) count_neighbors = count_neighbors + 1;

        r1 = row;
        c1 = col - 1;
        r2 = row;
        c2 = col + 1;
        r1 = r1 % 16;
        c1 = c1 % 16;
        r2 = r2 % 16;
        c2 = c2 % 16;

        if (current_q[(r1*16 + c1)]) count_neighbors = count_neighbors + 1;
        if (current_q[(r2*16 + c2)]) count_neighbors = count_neighbors + 1;

        r1 = row + 1;
        c1 = col - 1;
        r2 = row + 1;
        c2 = col;
        r3 = row + 1;
        c3 = col + 1;
        r1 = r1 % 16;
        c1 = c1 % 16;
        r2 = r2 % 16;
        c2 = c2 % 16;
        r3 = r3 % 16;
        c3 = c3 % 16;

        if (current_q[(r1*16 + c1)]) count_neighbors = count_neighbors + 1;
        if (current_q[(r2*16 + c2)]) count_neighbors = count_neighbors + 1;
        if (current_q[(r3*16 + c3)]) count_neighbors = count_neighbors + 1;
    endfunction

    // Generate neighbor counts for all cells
    genvar i, j;
    generate
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                // Compute neighbor count for cell (i, j)
                reg [7:0] count;
                count = count_neighbors(i, j);
                // Determine next state based on neighbor count
                if (count <= 1) begin
                    next_q[(i*16 + j)] = 0;
                end else if (count == 2) begin
                    next_q[(i*16 + j)] = current_q[(i*16 + j)];
                end else if (count == 3) begin
                    next_q[(i*16 + j)] = 1;
                end else begin
                    next_q[(i*16 + j)] = 0;
                end
            end
        end
    endgenerate

    // Load the initial state on the rising edge of load
    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            current_q <= next_q;
        end
    end

    // Assign output
    assign q = current_q;

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // Determine the current water level state
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 3; // Reset to state equivalent of being above s[2]
            prev_s <= 3'b111; // All sensors asserted (above s[2])
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        state <= 3; // Above s[2]
                    end else begin
                        state <= 2; // Between s[2] and s[1]
                    end
                end else begin
                    state <= 1; // Between s[1] and s[0]
                end
            end else begin
                state <= 0; // Below s[0]
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

    // Determine outputs based on current and previous states
    always @(posedge clk) begin
        if (state == 3) begin
            // Above s[2], flow rate should be zero
            fr2 <= 1'b0;
            fr1 <= 1'b0;
            fr0 <= 1'b0;
            dfr <= 1'b0;
        end else if (state == 2) begin
            // Between s[2] and s[1], nominal flow rate is fr0
            fr2 <= 1'b0;
            fr1 <= 1'b0;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else if (state == 1) begin
            // Between s[1] and s[0], nominal flow rate is fr0 and fr1
            fr2 <= 1'b0;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else if (state == 0) begin
            // Below s[0], flow rate is maximum (fr0, fr1, fr2)
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end

        // Check if the previous level was lower than the current level
        if (state == 2 && prev_s == 3'b111) begin
            dfr <= 1'b1;
        end else if (state == 1 && prev_s == 3'b110) begin
            dfr <= 1'b1;
        end else if (state == 0 && prev_s == 3'b100) begin
            dfr <= 1'b1;
        end else begin
            dfr <= 1'b0;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1'b1 && ground == 1'b0) begin
                next_state = FALLING;
                was_falling <= 1'b1;
            end else if (current_state == FALLING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                next_state = prev_direction ? WALK_LEFT : WALK_RIGHT;
            end else if (dig && current_state == WALK_LEFT && ground == 1'b1) begin
                next_state = DIGGING;
            end else if (dig && current_state == WALK_LEFT && ground == 1'b0) begin
                // Ignore dig while falling
            end else if (dig && current_state == DIGGING) begin
                // Continue digging
            end else if (current_state == DIGGING && ground == 1'b0) begin
                next_state = FALLING;
            end else if (current_state == DIGGING && ground == 1'b1) begin
                next_state = prev_direction ? WALK_LEFT : WALK_RIGHT;
            end else if (bump_left || bump_right) begin
                if (current_state == WALK_LEFT) begin
                    next_state = WALK_RIGHT;
                end else if (current_state == WALK_RIGHT) begin
                    next_state = WALK_LEFT;
                end
            end

            // Update current state
            current_state <= next_state;

            // Update outputs based on state
            case (current_state)
                WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                FALLING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    digging <= 1'b0;
                end
                DIGGING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end
            endcase
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // Determine current water level
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 3; // Reset to state equivalent of being above s[2]
            prev_s <= 3'b111; // All sensors asserted (above s[2])
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Update previous sensor state
            prev_s <= s;

            // Determine current water level
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        state <= 3; // Above s[2]
                    end else begin
                        state <= 2; // Between s[2] and s[1]
                    end
                end else begin
                    state <= 1; // Between s[1] and s[0]
                end
            end else begin
                state <= 0; // Below s[0]
            end

            // Set outputs based on state and previous sensor state
            case (state)
                3: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                1: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= (prev_s < s) ? 1'b1 : 1'b0;
                end
                0: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg direction; // 0 for left, 1 for right
    reg was_walking_left; // to remember direction before falling
    reg was_digging; // to remember if was digging before falling

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            direction <= 0;
            was_walking_left <= 1;
            was_digging <= 0;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
        end else begin
            current_state <= next_state;
            direction <= next_state == WALK_LEFT ? 0 : 1;
            was_walking_left <= (next_state == WALK_LEFT) ? 1 : (next_state == WALK_RIGHT) ? 0 : was_walking_left;
            was_digging <= (next_state == DIGGING) ? 1 : (next_state == FALLING) ? 0 : was_digging;
            walk_left <= (next_state == WALK_LEFT) ? 1 : 0;
            walk_right <= (next_state == WALK_RIGHT) ? 1 : 0;
            aaah <= (next_state == FALLING) ? 1 : 0;
            digging <= (next_state == DIGGING) ? 1 : 0;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;
        case (current_state)
            WALK_LEFT: begin
                if (dig) begin
                    next_state = DIGGING;
                end else if (!ground) begin
                    next_state = FALLING;
                end else begin
                    if (bump_right) begin
                        next_state = WALK_RIGHT;
                    end
                end
            end
            WALK_RIGHT: begin
                if (dig) begin
                    next_state = DIGGING;
                end else if (!ground) begin
                    next_state = FALLING;
                end else begin
                    if (bump_left) begin
                        next_state = WALK_LEFT;
                    end
                end
            end
            FALLING: begin
                if (ground) begin
                    next_state = was_walking_left ? WALK_LEFT : WALK_RIGHT;
                end
            end
            DIGGING: begin
                if (ground) begin
                    next_state = was_walking_left ? WALK_LEFT : WALK_RIGHT;
                end
            end
        endcase
    end

endmodule

