module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1'b1 && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == FALLING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                aaah <= 1'b0;
            end else if (dig && current_state == WALK_LEFT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (dig && current_state == WALK_RIGHT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                digging <= 1'b0;
            end else if (current_state == WALK_LEFT && (bump_left || bump_right)) begin
                next_state = WALK_RIGHT;
                walk_left <= 1'b0;
                walk_right <= 1'b1;
            end else if (current_state == WALK_RIGHT && (bump_left || bump_right)) begin
                next_state = WALK_LEFT;
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end

            // Update state
            current_state <= next_state;

            // Update direction if not falling or digging
            if (current_state != FALLING && current_state != DIGGING) begin
                prev_direction <= walk_left;
            end

            // Update aaah and digging based on state
            if (current_state == FALLING) begin
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == DIGGING) begin
                aaah <= 1'b0;
                digging <= 1'b1;
            end else begin
                aaah <= 1'b0;
                digging <= 1'b0;
            end
        end
    end

endmodule

