module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State machine states
    typedef enum reg [2:0] {
        STATE_LOW,      // Below s[0]
        STATE_MID_LOW,  // Between s[1] and s[0]
        STATE_MID_HIGH, // Between s[2] and s[1]
        STATE_HIGH      // Above s[2]
    } state_t;

    state_t current_state, next_state;
    reg [2:0] prev_sensors;

    // State transition and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_LOW;
            prev_sensors <= 3'b111; // All sensors asserted (water level low for a long time)
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            prev_sensors <= s;
            case (current_state)
                STATE_LOW: begin
                    if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b1;
                    end
                end

                STATE_MID_LOW: begin
                    if (s[1]) begin
                        next_state <= STATE_MID_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b1;
                    end
                end

                STATE_MID_HIGH: begin
                    if (s[2]) begin
                        next_state <= STATE_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end else if (s[1]) begin
                        next_state <= STATE_MID_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b1;
                    end
                end

                STATE_HIGH: begin
                    if (s[2]) begin
                        next_state <= STATE_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end else if (s[1]) begin
                        next_state <= STATE_MID_HIGH;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else if (s[0]) begin
                        next_state <= STATE_MID_LOW;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else begin
                        next_state <= STATE_LOW;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b1;
                    end
                end

                default: begin
                    next_state <= STATE_LOW;
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b1;
                end
            endcase

            current_state <= next_state;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1'b1 && ground == 1'b0) begin
                next_state = FALLING;
                was_falling <= 1'b1;
            end else if (current_state == FALLING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                next_state = prev_direction ? WALK_RIGHT : WALK_LEFT;
            end else if (dig && current_state == WALK_LEFT && ground == 1'b1) begin
                next_state = DIGGING;
            end else if (dig && current_state == WALK_RIGHT && ground == 1'b1) begin
                next_state = DIGGING;
            end else if (current_state == DIGGING && ground == 1'b0) begin
                next_state = FALLING;
            end else if (current_state == DIGGING && ground == 1'b1) begin
                next_state = prev_direction ? WALK_RIGHT : WALK_LEFT;
            end else if (current_state == WALK_LEFT && (bump_left || bump_right)) begin
                next_state = WALK_RIGHT;
            end else if (current_state == WALK_RIGHT && (bump_left || bump_right)) begin
                next_state = WALK_LEFT;
            end

            // Update current state
            current_state <= next_state;

            // Update outputs based on state
            case (current_state)
                WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                FALLING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    digging <= 1'b0;
                end
                DIGGING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end
            endcase
        end
    end

endmodule
